let velocity = 0;
let gridSize = 300;
let cellSize = 10;
let amplitude = 20;
let wavelength = 30;

function setup() {
	createCanvas(900, 700, WEBGL);
	noFill();
	strokeWeight(1);
}

function draw() {
	background(255);
	rotateX(PI / 3);
   orbitControl();
	for (let y = -gridSize; y <= gridSize; y += cellSize) {
		beginShape();
		for (let x = -gridSize; x <= gridSize; x += cellSize) {
			let d = dist(x, y, 0, 0);
			let z = amplitude * sin(d / wavelength - velocity);
			vertex(x, y, z);
		}
		endShape();
	}

	for (let x = -gridSize; x <= gridSize; x += cellSize) {
		beginShape();
		for (let y = -gridSize; y <= gridSize; y += cellSize) {
			var d = dist(x, y, 0, 0);
			var z = amplitude * sin(d / wavelength - velocity);
			vertex(x, y, z);
		}
		endShape();
	}
	velocity += 0.1;
}
